/* Local Workspace orchestration.
 *
 * Repository files are compared with an export and a machine-local baseline.
 * Incoming JSON is applied before a new export. Markdown is never generated by
 * Exporter in this mode: bound reading notes are owned by Better Notes, and all
 * other content/ files remain ordinary user files.
 */

ZoteroGitHubSync.Workspace = {
	BINDINGS_FILE: '.zotero-sync/bindings.json',
	STATE_VERSION: 2,
	_pollTimer: null,
	_pollFingerprint: '',

	normalize(path) {
		return String(path || '').replace(/\\/g, '/').replace(/\/+$/, '');
	},

	/**
	 * Obsidian persists its open panes and window layout in these files. They are
	 * deliberately machine-local: sharing them makes two otherwise independent
	 * computers continually modify the same workspace state.
	 */
	isMachineLocalPath(path) {
		return /(?:^|\/)\.obsidian\/workspace(?:-mobile)?\.json$/i.test(this.normalize(path));
	},

	generatedStatePaths(config) {
		return {
			bindings: `${config.basePath}/${this.BINDINGS_FILE}`,
			manifest: `${config.basePath}/.zotero-sync/manifest.json`,
		};
	},

	machineLocalPathspecs(config) {
		return config.managedPaths.map(root => `:(exclude)${root}/.obsidian/workspace*.json`);
	},

	resolve(config, relative) {
		if (!config.workspacePath || !PathUtils.isAbsolute(config.workspacePath)) {
			throw new Error('Configure an absolute Local Workspace repository path.');
		}
		let segments = String(relative || '').replace(/\\/g, '/').split('/');
		if (!segments.length || segments.some(s => !s || s === '.' || s === '..')) {
			throw new Error(`Unsafe workspace path: ${relative}`);
		}
		let target = PathUtils.join(config.workspacePath, ...segments);
		let root = this.normalize(config.workspacePath).toLowerCase();
		let normalized = this.normalize(target).toLowerCase();
		if (normalized !== root && !normalized.startsWith(`${root}/`)) {
			throw new Error(`Path leaves the workspace: ${relative}`);
		}
		return target;
	},

	relative(config, absolute) {
		let root = this.normalize(config.workspacePath);
		let target = this.normalize(absolute);
		let prefix = `${root}/`;
		if (target.toLowerCase().startsWith(prefix.toLowerCase())) return target.slice(prefix.length);
		throw new Error(`Path is outside the workspace: ${absolute}`);
	},

	bindingPath(config) {
		return this.resolve(config, `${config.basePath}/${this.BINDINGS_FILE}`);
	},

	statePath(config) {
		// Local coordination is independent of GitHub transport, repository and
		// branch. Two cloud configurations for the same workspace must share the
		// same Zotero <-> mirror baseline.
		let identity = [this.normalize(config.workspacePath).toLowerCase(), config.basePath].join('\n');
		let id = Zotero.Utilities.Internal.md5(identity, false);
		return PathUtils.join(Zotero.Profile.dir, 'zotero-quartz-workspace', `state-${id}.json`);
	},

	async loadState(config) {
		try {
			let path = this.statePath(config);
			if (!await IOUtils.exists(path)) return null;
			let data = await IOUtils.readJSON(path);
			if (data?.version !== this.STATE_VERSION || !data.files) return null;
			return { files: new Map(Object.entries(data.files)) };
		}
		catch (e) { ZoteroGitHubSync.logError(e); return null; }
	},

	async saveState(config, files) {
		let path = this.statePath(config);
		let ordered = {};
		for (let key of [...files.keys()].sort()) ordered[key] = files.get(key);
		await IOUtils.makeDirectory(PathUtils.parent(path), { ignoreExisting: true });
		await IOUtils.writeJSON(path, { version: this.STATE_VERSION, files: ordered }, { tmpPath: `${path}.tmp` });
	},

	async removeMirrorPaths(config, paths) {
		let removed = [];
		for (let path of paths) {
			let absolute = this.resolve(config, `${config.basePath}/${path}`);
			if (await IOUtils.exists(absolute)) {
				await IOUtils.remove(absolute, { recursive: false });
				removed.push(`${config.basePath}/${path}`);
			}
		}
		return removed;
	},

	async applyDeletedMirrorItems(paths) {
		let applied = [];
		let unresolved = [];
		for (let path of paths) {
			let info = ZoteroGitHubSync.Planner.importable(path);
			if (info?.kind !== 'item') {
				unresolved.push(path);
				continue;
			}
			let libraryID = ZoteroGitHubSync.Importer._resolveLibraryID(info.library);
			let item = libraryID !== null ? Zotero.Items.getByLibraryAndKey(libraryID, info.key) : null;
			if (item && !item.deleted) {
				item.deleted = true;
				await item.saveTx();
			}
			applied.push(path);
		}
		return { applied, unresolved };
	},

	validateBindings(value) {
		let rows = Array.isArray(value?.bindings) ? value.bindings : [];
		let seenNotes = new Set();
		let seenPaths = new Set();
		let bindings = [];
		for (let row of rows) {
			if (!row?.library || !/^[A-Z0-9]{8}$/.test(row.parentKey || '')
				|| !/^[A-Z0-9]{8}$/.test(row.noteKey || '')) continue;
			let rawSegments = String(row.path || '').replace(/\\/g, '/').split('/');
			if (rawSegments.some(s => !s || s === '.' || s === '..')) continue;
			let path;
			try { path = ZoteroGitHubSync.Utils.normalizeBasePath(row.path); }
			catch (e) { continue; }
			let identity = `${JSON.stringify(row.library)}:${row.noteKey}`;
			let folded = path.toLowerCase();
			if (seenNotes.has(identity) || seenPaths.has(folded)) continue;
			seenNotes.add(identity); seenPaths.add(folded);
			bindings.push({ ...row, path, images: Array.isArray(row.images) ? row.images : [] });
		}
		return bindings.sort((a, b) => a.path.localeCompare(b.path));
	},

	mergeBindings(localValue, remoteValue) {
		let merged = new Map();
		for (let row of this.validateBindings(remoteValue)) {
			merged.set(`${JSON.stringify(row.library)}:${row.noteKey}`, row);
		}
		for (let row of this.validateBindings(localValue)) {
			let key = `${JSON.stringify(row.library)}:${row.noteKey}`;
			let previous = merged.get(key);
			// A binding is generated by the plugin, so its timestamp is a safe
			// deterministic tie-breaker. Prefer the local value on an exact tie.
			if (!previous || String(row.updated || '') >= String(previous.updated || '')) merged.set(key, row);
		}
		return this.validateBindings({ bindings: [...merged.values()] });
	},

	transportChangedCount(result) {
		if (Array.isArray(result?.changed)) return result.changed.length;
		return (Number(result?.uploaded) || 0) + (Number(result?.deletedRemote) || 0);
	},

	async cloudBootstrapReady(config) {
		if (config.workspaceTransport !== 'github-api' || !config.workspacePath) return true;
		return IOUtils.exists(ZoteroGitHubSync.WorkspaceAPITransport.statePath(config));
	},

	async resetSetupState(config) {
		await IOUtils.remove(this.statePath(config), { ignoreAbsent: true });
		if (config.workspaceTransport === 'github-api') {
			await IOUtils.remove(ZoteroGitHubSync.WorkspaceAPITransport.statePath(config), { ignoreAbsent: true });
		}
	},

	async loadBindings(config) {
		let path = this.bindingPath(config);
		try {
			if (!await IOUtils.exists(path)) return [];
			let data = await IOUtils.readJSON(path);
			return this.validateBindings(data);
		}
		catch (e) { throw new Error(`Cannot read bindings: ${e.message || e}`); }
	},

	async saveBindings(config, bindings) {
		let path = this.bindingPath(config);
		await IOUtils.makeDirectory(PathUtils.parent(path), { ignoreExisting: true });
		let value = { schema: 1, generator: 'zotero-quartz-workspace-sync', bindings: this.validateBindings({ bindings }) };
		let text = ZoteroGitHubSync.Exporter.stableStringify(value) + '\n';
		await this.writeBytesIfChanged(path, new TextEncoder().encode(text));
	},

	async writeBytesIfChanged(path, bytes) {
		if (await IOUtils.exists(path)) {
			let old = await IOUtils.read(path);
			if (old.length === bytes.length) {
				let same = true;
				for (let i = 0; i < old.length; i++) if (old[i] !== bytes[i]) { same = false; break; }
				if (same) return false;
			}
		}
		await IOUtils.makeDirectory(PathUtils.parent(path), { ignoreExisting: true });
		let tmpPath = `${path}.zqws-tmp`;
		await IOUtils.remove(tmpPath, { ignoreAbsent: true });
		await IOUtils.write(path, bytes, { tmpPath });
		return true;
	},

	async listFiles(root, prefix = '') {
		let found = [];
		if (!await IOUtils.exists(root)) return found;
		for (let child of await IOUtils.getChildren(root)) {
			let name = PathUtils.filename(child);
			let rel = prefix ? `${prefix}/${name}` : name;
			let stat;
			try { stat = await IOUtils.stat(child); }
			catch (e) { continue; }
			if (stat.type === 'directory') found.push(...await this.listFiles(child, rel));
			else if (stat.type === 'regular' && !name.endsWith('.zqws-tmp')) found.push({ path: rel, absolute: child, size: stat.size, mtime: stat.lastModified || 0 });
		}
		return found;
	},

	async scanManaged(config) {
		let files = new Map();
		let hashes = new Map();
		for (let root of config.managedPaths) {
			let absoluteRoot = this.resolve(config, root);
			for (let file of await this.listFiles(absoluteRoot)) {
				let path = `${root}/${file.path}`;
				if (this.isMachineLocalPath(path)) continue;
				if (files.has(path)) continue;
				let hash = await ZoteroGitHubSync.Files.cachedHash({
					path: file.absolute, size: file.size, mtime: file.mtime,
				}, 'git');
				files.set(path, file);
				hashes.set(path, hash);
			}
		}
		return { files, hashes };
	},

	isMirrorPath(path) {
		return /^(?:[^/]+\/)?(?:items\/(?:[A-Z0-9]{2}\/)?[A-Z0-9]{8}\.json|(?:collections|searches|settings|library)\.json|attachments(?:-lfs)?\/|\.zotero-sync\/manifest\.json)/.test(path);
	},

	async scanMirror(config) {
		let root = this.resolve(config, config.basePath);
		let tree = new Map();
		let hashes = new Map();
		for (let file of await this.listFiles(root)) {
			if (!this.isMirrorPath(file.path)) continue;
			let hash = await ZoteroGitHubSync.Files.cachedHash({ path: file.absolute, size: file.size, mtime: file.mtime }, 'git');
			let full = `${config.basePath}/${file.path}`;
			tree.set(full, { sha: file.absolute, size: file.size, hash });
			hashes.set(file.path, hash);
		}
		return { tree, hashes };
	},

	async hashExport(files) {
		let hashes = new Map();
		for (let [path, file] of files) {
			let hash = file.source
				? await ZoteroGitHubSync.Files.cachedHash(file.source, 'git')
				: await ZoteroGitHubSync.Utils.gitBlobSha(file.bytes);
			hashes.set(path, hash);
		}
		return hashes;
	},

	localClient() {
		return {
			getBlobText: async path => Zotero.File.getContentsAsync(path, 'utf-8'),
			getBlobBytes: async path => IOUtils.read(path),
			downloadBlob: async (source, target) => ZoteroGitHubSync.BetterNotes.copyAtomic(source, target),
		};
	},

	async importPaths(config, tree, paths, { force = false, onProgress = () => {} } = {}) {
		if (!paths.length) return { created: 0, updated: 0, skipped: 0, files: 0, failures: [] };
		let client = this.localClient();
		let libraries = ZoteroGitHubSync.Importer.groupByLibrary(
			new Map([...tree].filter(([full]) => paths.includes(full.slice(config.basePath.length + 1)))),
			config,
			{ keepEmpty: true }
		);
		return ZoteroGitHubSync.Importer._importGroups({
			client, config, token: '', libraries, cancel: ZoteroGitHubSync.Sync._cancel,
			onProgress, force, overwriteFiles: false, keepBoth: new Set(),
		});
	},

	async buildExport(config, onProgress) {
		let exportConfig = {
			...config,
			exportJSON: true,
			exportMarkdown: false,
			exportIndex: false,
			exportBibTeX: false,
			includeAttachments: config.includePDFsLocal || config.includeNoteImagesLocal,
			lfsEnabled: false,
			prune: false,
		};
		return ZoteroGitHubSync.Exporter.build({ config: exportConfig, onProgress });
	},

	async writeExport(config, files, keptPaths = []) {
		let changed = [];
		for (let [relative, file] of files) {
			let target = this.resolve(config, `${config.basePath}/${relative}`);
			let didWrite = false;
			if (file.bytes) didWrite = await this.writeBytesIfChanged(target, file.bytes);
			else if (file.source) {
				let targetHash = await ZoteroGitHubSync.BetterNotes.fileHash(target);
				let sourceHash = await ZoteroGitHubSync.BetterNotes.fileHash(file.source.path);
				if (targetHash !== sourceHash) {
					await ZoteroGitHubSync.BetterNotes.copyAtomic(file.source.path, target);
					didWrite = true;
				}
			}
			if (didWrite) changed.push(`${config.basePath}/${relative}`);
		}
		let managed = [...new Set([...files.keys(), ...keptPaths, this.BINDINGS_FILE])].sort();
		let listBytes = new TextEncoder().encode(ZoteroGitHubSync.Exporter.stableStringify(managed) + '\n');
		let listPath = this.resolve(config, `${config.basePath}/.zotero-sync/files.json`);
		if (await this.writeBytesIfChanged(listPath, listBytes)) changed.push(`${config.basePath}/.zotero-sync/files.json`);
		return changed;
	},

	applyKeepPrefixes(hashes, remoteHashes, prefixes) {
		let kept = [];
		for (let [path, hash] of remoteHashes) {
			if (!hashes.has(path) && prefixes.some(prefix => path.startsWith(prefix))) {
				hashes.set(path, hash);
				kept.push(path);
			}
		}
		return kept;
	},

	async preservePendingNoteJSON(config, files, bindings, results) {
		for (let result of results.filter(r => r.pending)) {
			let binding = bindings.find(b => b.path === result.path);
			if (!binding) continue;
			let parent = await ZoteroGitHubSync.BetterNotes.resolveItem(binding.library, binding.parentKey);
			if (!parent) continue;
			let library = Zotero.Libraries.get(parent.libraryID);
			let relative = ZoteroGitHubSync.Exporter.itemPath(
				ZoteroGitHubSync.Exporter.librarySlug(library), parent.key
			);
			let absolute = this.resolve(config, `${config.basePath}/${relative}`);
			if (await IOUtils.exists(absolute)) {
				// Keep the last repository JSON until Markdown and native HTML have
				// one coordinated winner. This prevents a third stale representation
				// from being committed during a two-sided note conflict.
				files.set(relative, { bytes: await IOUtils.read(absolute) });
			}
			else {
				files.delete(relative);
			}
		}
	},

	async syncNow({ trigger = 'manual', silent = false, remote = true } = {}) {
		let config = ZoteroGitHubSync.Prefs.getConfig();
		if (!config.workspacePath) return { status: 'not-configured', added: 0, updated: 0, deleted: 0, warnings: [] };
		if (!config.basePath) throw new Error('Local Workspace requires a non-empty Zotero mirror folder (normally "zotero").');
		if (remote && !config.managedPaths.length) throw new Error('Configure at least one managed workspace path.');
		let warnings = [];
		let pending = 0;
		let git = null;
		let api = null;
		let apiReady = false;
		let apiHadState = true;
		let gitState = { status: 'not-run' };
		if (remote && config.workspaceTransport === 'github-api') {
			apiHadState = await this.cloudBootstrapReady(config);
			let token = await ZoteroGitHubSync.Prefs.getToken();
			if (!config.owner || !config.repo || !config.branch || !token) {
				throw new Error('Configure the GitHub owner, repository, branch, and token for API transport.');
			}
			ZoteroGitHubSync.Sync._updateProgress({ phase: 'downloading', message: ZoteroGitHubSync.getString('progress.readingCloud') });
			api = new ZoteroGitHubSync.WorkspaceAPITransport(config, token);
			try {
				let prepared = await api.prepare();
				warnings.push(...prepared.warnings);
				gitState = { status: prepared.status };
				apiReady = true;
			}
			catch (e) {
				if (!apiHadState) {
					throw new Error(`Initial GitHub workspace download failed; local export is still paused for safety: ${e.message || e}`);
				}
				pending++;
				gitState = { status: 'remote-unavailable' };
				warnings.push(`GitHub API transport is unavailable; local workspace edits are preserved: ${e.message || e}`);
			}
		}
		else if (remote) {
			git = new ZoteroGitHubSync.LocalGit(config);
			await git.validate();
			gitState = await git.fetchAndFastForward();
			if (['blocked', 'diverged', 'remote-pending'].includes(gitState.status)) {
				pending++;
				warnings.push(gitState.reason || `Git state: ${gitState.status}`);
			}
			else if (gitState.status === 'offline') {
				warnings.push(`Git fetch unavailable; local work is preserved: ${gitState.reason}`);
			}
		}

		ZoteroGitHubSync.Sync._updateProgress({ phase: 'collecting', message: ZoteroGitHubSync.getString('progress.readingLocal') });
		await ZoteroGitHubSync.Files.loadCache();
		let before = await this.scanMirror(config);
		let state = await this.loadState(config);
		let imported = { created: 0, updated: 0, skipped: 0, files: 0, failures: [] };
		if (!state && before.tree.size) {
			// Safe bootstrap: importer never deletes. Stable keys prevent duplicate
			// items, and an empty new computer is populated before any export.
			let all = [...before.hashes.keys()];
			imported = await this.importPaths(config, before.tree, all, {
				onProgress: message => ZoteroGitHubSync.Sync._updateProgress({ phase: 'importing', message }),
			});
			warnings.push(...(imported.failures || []));
			pending += (imported.failures || []).length;
		}

		let firstExport = await this.buildExport(config, message => ZoteroGitHubSync.Sync._updateProgress({ phase: 'collecting', message }));
		let localHashes = await this.hashExport(firstExport.files);
		this.applyKeepPrefixes(localHashes, before.hashes, firstExport.keepPrefixes || []);
		let plan = ZoteroGitHubSync.Planner.plan({
			local: localHashes,
			remote: before.hashes,
			base: state?.files || null,
			prune: true,
		});
		if (state) {
			// In the always-on local layer, deletion wins even if the surviving
			// mirror copy changed later. Move those cases out of "incoming" and
			// into the deletion path before importing anything.
			let deletedLocally = plan.incoming.filter(path => state.files.has(path) && !localHashes.has(path));
			plan.incoming = plan.incoming.filter(path => !deletedLocally.includes(path));
			plan.delete.push(...deletedLocally);
			plan.delete.sort();
		}
		if (state && plan.incoming.length) {
			let incoming = await this.importPaths(config, before.tree, plan.incoming, {
				force: true,
				onProgress: message => ZoteroGitHubSync.Sync._updateProgress({ phase: 'importing', message }),
			});
			for (let key of ['created', 'updated', 'skipped', 'files']) imported[key] += incoming[key] || 0;
			let incomingFailures = incoming.failures || [];
			imported.failures.push(...incomingFailures);
			warnings.push(...incomingFailures);
			pending += incomingFailures.length;
		}
		let mirrorDeletes = state ? await this.applyDeletedMirrorItems(plan.restore) : { applied: [], unresolved: [] };
		let removedMirror = state ? await this.removeMirrorPaths(config, plan.delete) : [];
		let unresolved = [...plan.conflicts, ...plan.diverged, ...plan.overwrite];
		if (unresolved.length) {
			pending += unresolved.length;
			warnings.push(`Zotero mirror needs review: ${unresolved.slice(0, 8).join(', ')}${unresolved.length > 8 ? '…' : ''}`);
		}

		let bindings = await this.loadBindings(config);
		let discovered = await ZoteroGitHubSync.BetterNotes.discoverBindings(bindings, config);
		warnings.push(...discovered.warnings);
		pending += discovered.warnings.length;
		let noteResult = await ZoteroGitHubSync.BetterNotes.coordinateAll(bindings, config, {
			relocationConflicts: discovered.relocationConflicts,
		});
		pending += noteResult.pending;
		warnings.push(...noteResult.warnings);
		await this.saveBindings(config, bindings);

		// Better Notes may have changed native note HTML. Build again so JSON and
		// Markdown describe the same coordinated logical note.
		let finalExport = await this.buildExport(config, message => ZoteroGitHubSync.Sync._updateProgress({ phase: 'collecting', message }));
		await this.preservePendingNoteJSON(config, finalExport.files, bindings, noteResult.results);
		let finalHashes = await this.hashExport(finalExport.files);
		let keptPaths = this.applyKeepPrefixes(finalHashes, before.hashes, finalExport.keepPrefixes || []);
		if (state) {
			// Better Notes coordination can trash a child note after the first
			// export (for example when its Markdown was deleted). Remove the now
			// stale mirror JSON in this same transaction so it cannot be imported
			// back on the next run.
			let lateDeletes = [...before.hashes.keys()]
				.filter(path => state.files.has(path) && !finalHashes.has(path));
			removedMirror.push(...await this.removeMirrorPaths(config, lateDeletes));
		}
		let changed = await this.writeExport(config, finalExport.files, keptPaths);
		let transportResult = { status: 'not-run' };
		let remoteUnsafe = config.workspaceTransport === 'system-git'
			&& ['blocked', 'diverged', 'remote-pending'].includes(gitState.status);
		if (remote && apiReady) {
			ZoteroGitHubSync.Sync._updateProgress({ phase: 'committing', message: ZoteroGitHubSync.getString('progress.publishingAPI') });
			transportResult = await api.finish(trigger);
			pending += transportResult.pending || 0;
			warnings.push(...(transportResult.warnings || []));
		}
		else if (remote && config.workspaceTransport === 'github-api') {
			transportResult = { status: 'remote-unavailable', commit: null };
		}
		else if (remote && config.autoCommit && !remoteUnsafe) {
			ZoteroGitHubSync.Sync._updateProgress({ phase: 'committing', message: ZoteroGitHubSync.getString('progress.committingWorkspace') });
			let message = (config.commitMessage || 'Research workspace sync: {changes} ({date})')
				.replace(/\{changes\}/g, `${changed.length} file(s)`)
				.replace(/\{added\}/g, String(changed.length))
				.replace(/\{updated\}/g, '0')
				.replace(/\{deleted\}/g, '0')
				.replace(/\{trigger\}/g, trigger)
				.replace(/\{date\}/g, ZoteroGitHubSync.Utils.isoDate());
			transportResult = await git.commitAndPush(config.managedPaths, message, {
				push: config.autoPush,
				ignoredPathspecs: this.machineLocalPathspecs(config),
			});
			if (['blocked', 'staged-pending', 'commit-failed', 'push-pending'].includes(transportResult.status)) {
				pending++;
				warnings.push(transportResult.reason || transportResult.status);
			}
		}
		else if (remote && !config.autoCommit && changed.length) {
			warnings.push('Workspace files are ready but automatic commit is disabled.');
		}

		let localPending = unresolved.length + noteResult.pending + discovered.warnings.length + (imported.failures || []).length;
		if (!localPending) await this.saveState(config, finalHashes);
		let coordinatedNote = noteResult.results.some(result => ![
			'up-to-date', 'bound', 'editing', 'conflict', 'unsupported-markdown', 'image-conflict', 'waiting-identity',
		].includes(result.status));
		let localStatus = localPending ? 'pending'
			: (changed.length || removedMirror.length || mirrorDeletes.applied.length || imported.updated || imported.created || coordinatedNote
				? 'local-complete' : 'up-to-date');
		let status = remote
			? (pending ? 'pending' : (transportResult.status === 'pushed' ? 'pushed' : transportResult.status))
			: localStatus;
		let localChanged = changed.length + removedMirror.length;
		let remoteChanged = remote ? this.transportChangedCount(transportResult) : 0;
		ZoteroGitHubSync.Prefs.set('localStatus', JSON.stringify({
			status: localStatus,
			pending: localPending,
			at: new Date().toISOString(),
		}));
		if (remote) ZoteroGitHubSync.Prefs.set('cloudStatus', JSON.stringify({
			status,
			transport: config.workspaceTransport,
			remote: transportResult.status,
			changed: remoteChanged,
			pending,
			at: new Date().toISOString(),
		}));
		await ZoteroGitHubSync.Files.saveCache();
		// Do not make the watcher queue a second run merely because this run wrote
		// the mirror or a bound Markdown file itself.
		this._pollFingerprint = await this.fingerprint(config);
		return {
			status,
			added: remote ? remoteChanged : localChanged,
			localChanged,
			remoteChanged,
			updated: imported.updated + imported.created,
			deleted: transportResult.deletedRemote || 0,
			commit: transportResult.commit || null,
			pending,
			localPending,
			warnings,
			transport: transportResult,
			notes: noteResult.results,
			layer: remote ? 'cloud' : 'local',
		};
	},

	async openReadingNote(item) {
		let config = ZoteroGitHubSync.Prefs.getConfig();
		if (!config.workspacePath || !PathUtils.isAbsolute(config.workspacePath) || !await IOUtils.exists(config.workspacePath)) {
			throw new Error('Configure an existing absolute Local Workspace path.');
		}
		let bindings = await this.loadBindings(config);
		let data = { bindings, save: () => this.saveBindings(config, bindings) };
		return ZoteroGitHubSync.BetterNotes.openReadingNote(item, config, data);
	},

	obsidianURI(config, absolutePath) {
		let vault = config.obsidianVaultPath;
		if (!vault || !PathUtils.isAbsolute(vault)) throw new Error('Configure the absolute Obsidian Vault path.');
		let root = this.normalize(vault);
		let target = this.normalize(absolutePath);
		if (!target.toLowerCase().startsWith(`${root}/`.toLowerCase())) {
			throw new Error('The reading note is outside the configured Obsidian Vault.');
		}
		let relative = target.slice(root.length + 1);
		let name = config.obsidianVaultName || PathUtils.filename(vault);
		return `obsidian://open?vault=${encodeURIComponent(name)}&file=${encodeURIComponent(relative)}`;
	},

	async fingerprint(config) {
		let parts = [];
		let roots = new Set([
			...config.managedPaths,
			config.basePath,
			String(config.papersPath || '').split('/')[0],
			String(config.assetsPath || '').split('/')[0],
		].filter(Boolean));
		for (let root of roots) {
			for (let file of await this.listFiles(this.resolve(config, root))) {
				parts.push(`${root}/${file.path}\0${file.size}\0${file.mtime}`);
			}
		}
		return Zotero.Utilities.Internal.md5(parts.sort().join('\n'), false);
	},

	startWatcher() {
		this.stopWatcher();
		let config = ZoteroGitHubSync.Prefs.getConfig();
		if (!config.workspacePath || !PathUtils.isAbsolute(config.workspacePath)) return;
		this.fingerprint(config).then(value => { this._pollFingerprint = value; }).catch(() => {});
		this._pollTimer = setInterval(async () => {
			try {
				let current = ZoteroGitHubSync.Prefs.getConfig();
				if (ZoteroGitHubSync.Sync.isRunning) return;
				let value = await this.fingerprint(current);
				if (this._pollFingerprint && value !== this._pollFingerprint) {
					ZoteroGitHubSync.Sync.scheduleWorkspaceChange();
				}
				this._pollFingerprint = value;
			}
			catch (e) { ZoteroGitHubSync.logError(e); }
		}, 5 * 1000);
	},

	stopWatcher() {
		if (this._pollTimer) clearInterval(this._pollTimer);
		this._pollTimer = null;
	},
};
